const r = await tools.exec_command({cmd:"PYTHONPATH=tools /tmp/pumpmodem-cleanup-venv/bin/python -B - <<'PY'
import time
import numpy as np
from triad_dynamic_joint import BlockProjection
p = BlockProjection.make(64, 64., ((0., 0.),), ())
x = np.random.default_rng(2).normal(size=(3, 2, 2, 64)) + 1j*np.random.default_rng(3).normal(size=(3, 2, 2, 64))
ref = lambda: np.fft.fft(x, axis=-1, norm='ortho')[..., p.indices]
opt = lambda: p.numpy(x)
assert np.allclose(ref(), opt(), rtol=1e-12, atol=1e-12)
for fn in (ref, opt):
    fn()
for name, fn in [('full_fft_then_select', ref), ('dc_sum', opt)]:
    durations=[]
    for _ in range(5):
        t=time.perf_counter()
        for _ in range(5000): fn()
        durations.append(time.perf_counter()-t)
    print(name, 'median_seconds_5000_calls', sorted(durations)[2])
print('case_shape', x.shape, 'selected_modes', len(p.indices), 'allclose', True)
