const r = await tools.exec_command({cmd:"PYTHONPATH=tools /tmp/pumpmodem-cleanup-venv/bin/python -B - <<'PY'
import numpy as np
from triad_dynamic_joint import BlockProjection
p = BlockProjection.make(64, 64., ((0., 0.),), ())
for dt in (np.float32, np.float64, np.complex64, np.complex128):
    x = np.arange(128, dtype=dt).reshape(2, 64)
    if np.issubdtype(dt, np.complexfloating): x = x * (1+2j)
    got = p.numpy(x); ref = np.fft.fft(x, axis=-1, norm='ortho')[..., p.indices]
    assert got.shape == ref.shape and got.dtype == ref.dtype
    assert np.allclose(got, ref, rtol=1e-6, atol=1e-7)
for value, expected in ((np.zeros(63), ValueError), (np.asarray(1.), IndexError)):
    try: p.numpy(value)
    except expected as exc: print(type(exc).__name__, str(exc))
    else: raise AssertionError('accepted an input the reference rejects')
valid = BlockProjection.valid_rows(64., np.array([True, False, True]))
a = np.arange(3.)
assert np.array_equal(valid.numpy(a), a[[0, 2]])
q = BlockProjection.make(64, 64., ((1., 1.),), ())
a = np.arange(64.)
assert np.array_equal(q.numpy(a), np.fft.fft(a, norm='ortho')[..., q.indices])
print('dtype/shape for four numeric dtypes; error cases; valid-rows; non-DC fallback: PASS')
